INSERT INTO `equipment` VALUES (100,10,'EQ-EEE-001','AC Shunt Motor & DC Generator Set','Electrical','Used to study speed control and loading characteristics of DC machines.','Available','2023-01-15','https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=600&auto=format&fit=crop',5),(101,10,'EQ-EEE-002','3-Phase Alternator Sync Panel','Electrical','Sync and load-sharing panel for 3-Phase alternating current machines.','Available','2023-03-22','https://images.unsplash.com/photo-1517430816045-df4b7de11d1d?w=600&auto=format&fit=crop',5),(102,10,'EQ-EEE-003','3-Phase Transformer Trainer Kit','Electrical','Equipped with multi-tap winding panels for voltage ratio studies.','Available','2023-05-18','https://images.unsplash.com/photo-1620283085439-39620a1e21c4?w=600&auto=format&fit=crop',5),(103,11,'EQ-EEE-004','Kelvin Double Bridge Trainer','Measurement','High-precision resistance bridge setup to measure low resistance values.','Available','2022-08-10','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=600&auto=format&fit=crop',5),(106,12,'EQ-EEE-007','Servo Motor Control Hardware Unit','Control Systems','Feedback control rig for studying angular position/velocity tuning.','Available','2023-09-05','https://images.unsplash.com/photo-1518770660439-4636190af475?w=600&auto=format&fit=crop',5),(200,20,'EQ-MECH-001','Steam Boiler & Turbine Test Rig','Thermal','Thermal rig to evaluate steam energy efficiency and turbine torque.','Available','2022-06-25','https://images.unsplash.com/photo-1616401784845-180882ba9ba8?w=600&auto=format&fit=crop',5),(201,20,'EQ-MECH-002','IC Engine Test Setup (Variable Compression)','Thermal','Multi-fuel engine rig with computerized torque and pressure sensors.','Available','2022-10-18','https://images.unsplash.com/photo-1486006920555-c77dce18193b?w=600&auto=format&fit=crop',5),(202,21,'EQ-MECH-003','Venturimeter and Orifice Calibration Rig','Fluids','Fluid dynamics piping to calibrate discharge coefficients.','Available','2023-02-12','https://images.unsplash.com/photo-1504917595217-d4dc5ebe6122?w=600&auto=format&fit=crop',5),(204,22,'EQ-MECH-005','Universal Testing Machine (UTM) 100kN','Testing','Measures tensile, compressive, and bending strength of materials.','Available','2021-08-30','https://images.unsplash.com/photo-1581092335397-9583fe92d232?w=600&auto=format&fit=crop',5),(206,23,'EQ-MECH-007','CNC Lathe & Mechatronics Trainer Kit','CAD/CAM','Automated manufacturing center with programmable tool paths.','Available','2022-05-14','https://images.unsplash.com/photo-1615840287214-7fe58a8b668f?w=600&auto=format&fit=crop',5),(207,24,'EQ-MECH-008','Voxelab Industrial 3D Printer','3D Printing','Dual-extruder additive manufacturing system for functional prototyping.','Available','2023-08-11','https://images.unsplash.com/photo-1634973357973-f2ed255753e1?w=600&auto=format&fit=crop',5),(300,30,NULL,'Digital Storage Oscilloscope Tektronix','General',NULL,'Available',NULL,'https://images.unsplash.com/photo-1601524909162-be87252be298?w=600&auto=format&fit=crop',5),(301,30,'EQ-ECE-002','Arbitrary Function Generator Keysight','Measurement','Generates standard sine, square, triangle, and custom arbitrary waveforms.','Available','2023-04-12','https://images.unsplash.com/photo-1581093196867-9f6c5e57a8a6?w=600&auto=format&fit=crop',5),(302,31,'EQ-ECE-003','FPGA Spartan 6 Development Board','VLSI','Programmable logic array trainer for digital design synthesis.','Available','2022-09-08','https://images.unsplash.com/photo-1607604276583-eef5d076aa5f?w=600&auto=format&fit=crop',5),(303,33,'EQ-CSE-001','High Performance Server Dell PowerEdge','Server','Workstation for networking and OS virtualization.','Available','2023-02-28','https://images.unsplash.com/photo-1547082299-de196ea013d6?w=600&auto=format&fit=crop',5),(304,34,'EQ-CSE-002','Oracle Database Server Machine','Server','Dedicated database engine for DBMS indexing and query profiling.','Available','2023-04-12','https://images.unsplash.com/photo-1600132806370-bf17e65e942f?w=600&auto=format&fit=crop',5),(305,35,'EQ-CSE-004','Object Oriented Paradigm Lab Workstation','Workstation','Workstation configured with OOP compilers and modelling software.','Available','2023-05-10','https://images.unsplash.com/photo-1518770660439-4636190af475?w=600&auto=format&fit=crop',5),(308,31,NULL,'Desktop Computer Dell OptiPlex','General',NULL,'Available',NULL,'https://images.unsplash.com/photo-1547082299-de196ea013d6?w=600&auto=format&fit=crop',5),(400,40,'EQ-CIV-001','Compression Testing Machine 2000kN','Testing','Tests compressive strength of concrete cylinders and cubes.','Available','2022-04-10','https://images.unsplash.com/photo-1581092226825-a6a2a5aee158?w=600&auto=format&fit=crop',5),(406,40,'EQ-CIV-007','Theodolite Digital Transit','Surveying','High precision angle measurement instrument for surveying.','Available','2022-12-14','https://images.unsplash.com/photo-1504307651254-35680f356dfd?w=600&auto=format&fit=crop',5),(503,50,'EQ-IT-004','Network Attached Storage (NAS) 16TB','Storage','Shared network storage for student backups.','Available','2022-09-22','https://images.unsplash.com/photo-1600132806370-bf17e65e942f?w=600&auto=format&fit=crop',5),(600,60,'EQ-AIDS-001','NVIDIA RTX A6000 Workstation','Compute','GPU compute workstation for training deep learning models.','Available','2023-04-10','https://images.unsplash.com/photo-1591453089816-0fbb971b454c?w=600&auto=format&fit=crop',5),(605,60,'EQ-AIDS-006','TurtleBot3 Mobile Robot Platform','Robotics','Mobile robot for ROS mapping and AI navigation algorithms.','Available','2023-01-20','https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=600&auto=format&fit=crop',5);
