DROP TABLE IF EXISTS `student_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `student_profiles` (
  `STUDENT_ID` bigint NOT NULL AUTO_INCREMENT,
  `USER_ID` bigint NOT NULL,
  `DEPARTMENT_ID` bigint NOT NULL,
  `REG_NO` varchar(50) NOT NULL,
  `YEAR` int NOT NULL,
  `SECTION` varchar(10) DEFAULT NULL,
  `NAME` varchar(100) NOT NULL,
  `EMAIL` varchar(150) NOT NULL,
  `STATUS` varchar(20) DEFAULT 'Active',
  `PHONE` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`STUDENT_ID`),
  UNIQUE KEY `USER_ID` (`USER_ID`),
  UNIQUE KEY `REG_NO` (`REG_NO`),
  UNIQUE KEY `EMAIL` (`EMAIL`),
  KEY `FK_STUDENT_DEPT` (`DEPARTMENT_ID`),
  CONSTRAINT `FK_STUDENT_DEPT` FOREIGN KEY (`DEPARTMENT_ID`) REFERENCES `departments` (`DEPARTMENT_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=728 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
